(r/"test/personal-marketer-dashboard.test.mjs").write_text("import test from 'node:test';import assert from 'node:assert/strict';import {mkdtempSync,rmSync,readFileSync} from 'node:fs';import {tmpdir} from 'node:os';import path from 'node:path';import {createHmac} from 'node:crypto';import vm from 'node:vm';\nimport {createApplication} from '../server/index.mjs';import {initialState,execute,engine} from '../server/engine.mjs';\nfunction fixture(){let state=initialState(false);for(const [id,rep,status]of [['L_perf_approved','u2','approved'],['L_perf_pending','u2','pending'],['L_perf_moved','u2','movein'],['L_perf_lost','u2','lost'],['L_perf_reassigned','u2','approved'],['L_perf_gaby_pending','u3','pending'],['L_perf_gaby_moved','u3','movein'],['L_perf_morgan','u1','approved']]){state=execute(state,'u0',{op:'createLead',createdId:id,args:[{first:'Synthetic',last:id,building:'hallmark',rep,payer:'Private pay'}]});const l=state.leads.find(l=>l.id===id);if(['movein','lost'].includes(status))l.stage=status;else l.programStatus=status;}state=execute(state,'u0',{op:'assign',expectedVersion:1,args:['L_perf_reassigned',{rep:'u3'}]});return state;}\ntest('dashboard credits original marketers, separates active approvals from completed/lost, and excludes other staff',()=>{const state=fixture(),tl=engine(state,'u0'),data=tl.marketerDashboard();assert.equal(data.marketers.length,2);const olivia=data.marketers.find(m=>m.id==='u2'),gaby=data.marketers.find(m=>m.id==='u3');assert.deepEqual(JSON.parse(JSON.stringify(olivia)),{id:'u2',name:'Olivia Fielder',broughtIn:5,movedIn:1,approved:2,notApproved:1,open:3,closedLost:1});assert.equal(gaby.broughtIn,2);assert.equal(gaby.movedIn,1);assert.equal(gaby.notApproved,1);assert.equal(gaby.approved,0);assert.equal(state.leads.find(l=>l.id==='L_perf_reassigned').rep,'u3');for(const uid of ['u1','u2','u3','u4','u5','u6'])assert.equal(engine(state,uid).marketerDashboard(),null);});\ntest('dashboard API is read-only and restricted to Steven, including delegated admins and Zach',async()=>{const dir=mkdtempSync(path.join(tmpdir(),'marketer-dashboard-')),secret='personal-metrics-test',delegate='a'.repeat(64),viewer='b'.repeat(64),app=await createApplication({schedule:false,env:{NODE_ENV:'test',APP_MODE:'live',PHI_APPROVED:'true',DATABASE_URL:'',SQLITE_PATH:path.join(dir,'db'),SESSION_SECRET:secret,DELEGATE_ACCESS_HASH:delegate,DELEGATE_ACCESS_EXPIRES_AT:new Date(Date.now()+3600000).toISOString(),VIEWER_ACCESS_HASH:viewer,VIEWER_ACCESS_EXPIRES_AT:'never',VIEWER_EMAIL:'zach@tharongroup.com',ZACH_LEAD_EDIT_ACCESS:'true'}});await new Promise(r=>app.server.listen(0,'127.0.0.1',r));const origin='http://127.0.0.1:'+app.server.address().port;try{const state=fixture();await app.store.query('UPDATE app_state SET data=$1 WHERE id=$2',[JSON.stringify(state),'main']);for(const uid of ['u0','u1','u2','u3','u4','u6']){const csrf=(uid==='u4'?delegate+'.':uid==='u6'?viewer+'.':'')+'csrf';await app.store.query('INSERT INTO sessions (token_hash,user_id,expires_at,csrf) VALUES ($1,$2,$3,$4)',[createHmac('sha256',secret).update(uid).digest('hex'),uid,Date.now()+60000,csrf]);const r=await fetch(origin+'/api/admin/marketer-dashboard',{headers:{Cookie:'tl_session='+uid}});assert.equal(r.status,uid==='u0'?200:403,uid);if(uid==='u0'){assert.equal(r.headers.get('cache-control'),'no-store');assert.equal((await r.json()).marketers.find(m=>m.id==='u2').broughtIn,5);}}assert.equal((await fetch(origin+'/api/admin/marketer-dashboard')).status,401);assert.equal((await fetch(origin+'/api/admin/marketer-dashboard',{method:'POST',headers:{Cookie:'tl_session=u0',Origin:origin,'X-CSRF-Token':'csrf'}})).status,405);assert.deepEqual(JSON.parse((await app.store.query('SELECT data FROM app_state WHERE id=$1',['main']))[0].data),state);}finally{await app.close();rmSync(dir,{recursive:true,force:true});}});\ntest('personal dashboard cards remain small and show approval labels clearly',()=>{const source=readFileSync(new URL('../site/app.js',import.meta.url),'utf8'),ctx={canMonitorStaff:()=>true,esc:s=>s,fmtRecorded:s=>s};vm.createContext(ctx);vm.runInContext(source.slice(source.indexOf('function performanceCards('),source.indexOf('async function loadPerformance(')),ctx);const html=ctx.performanceCards(engine(fixture(),'u0').marketerDashboard());for(const label of ['Olivia Fielder','Gaby Campos','Leads brought in','Moved in','Approved','Not approved','open referrals'])assert.ok(html.includes(label),label);ctx.canMonitorStaff=()=>false;assert.equal(ctx.performanceCards(engine(fixture(),'u0').marketerDashboard()),'');});\n")
