p.write_text(p.read_text()+'\ntest(\'overdue move-in alert opens only open referrals past their confirmed date, excluding future/today/moved/lost\',()=>{\n const ctx=uiContext(),tl=ctx.TL,{V,UI,filtered}=ctx.simpleTest,old=tl.Lead(\'L_simple_old\'),future=tl.Lead(\'L_simple_new\'),moved=tl.Lead(\'L_simple_private\');\n for(const l of [old,future,moved])l.referralProgress={programKey:[l.payer,l.building].join(\'|\'),assessment:\'pending\',approval:\'missing\',moveStatus:\'scheduled\',due:tl.T,note:\'\'};old.moveIn=tl.addDays(-2);future.moveIn=tl.addDays(1);moved.moveIn=tl.addDays(-3);moved.stage=\'movein\';\n assert.ok(V.today().includes(\'data-view="overdue-movein">Review overdue move-ins\'));UI.moveView=\'overdue-movein\';UI.simpleApproval=\'all\';UI.openDays=\'all\';assert.deepEqual(Array.from(filtered(),l=>l.id),[old.id]);assert.ok(V.leads().includes(\'<h2>Overdue move-ins</h2>\'));assert.ok(!V.leads().includes(\'L_simple_new\'));\n old.moveIn=tl.T;assert.equal(filtered().length,0);old.moveIn=tl.addDays(-2);old.stage=\'lost\';assert.equal(filtered().length,0);\n});\n')

